import json
import string
import random
from http.client import HTTPConnection
from socket import socket

USE_UNIX_SOCKETS = False
try:
    from socket import AF_UNIX, SOCK_STREAM
    USE_UNIX_SOCKETS = True
except ImportError:
    pass

IDCHARS = string.ascii_lowercase + string.digits

class UnixSocketMissing(Exception):
    pass


def jdumps(obj, encoding='utf-8'):
    return json.dumps(obj)


def jloads(json_string):
    return json.loads(json_string)


class ProtocolError(Exception):
    pass


class TransportMixIn(object):
    user_agent = 'jsonrpclib/1.0'

    def send_content(self, connection, request_body):
        connection.putheader("Content-Type", "application/json-rpc")
        connection.putheader("Content-Length", str(len(request_body)))
        connection.endheaders()
        if request_body:
            if type(request_body) == str:
                request_body = request_body.encode("utf8")
            connection.send(request_body)

    def getparser(self):
        target = JSONTarget()
        return JSONParser(target), target


class JSONParser(object):
    def __init__(self, target):
        self.target = target

    def feed(self, data):
        self.target.feed(data)

    def close(self):
        pass


class JSONTarget(object):
    def __init__(self):
        self.data = []

    def feed(self, data):
        self.data.append(data)

    def close(self):
        return ''.join([d.decode() for d in self.data])


class Transport(TransportMixIn):
    def __init__(self):
        TransportMixIn.__init__(self)


if USE_UNIX_SOCKETS:
    class UnixHTTPConnection(HTTPConnection):
        def connect(self):
            self.sock = socket(AF_UNIX, SOCK_STREAM)
            self.sock.connect(self.host)

    class UnixTransport(TransportMixIn):
        def make_connection(self, host):
            return UnixHTTPConnection(host)


class Payload(dict):
    def __init__(self, rpcid=None, version=2.0):
        self.id = rpcid
        self.version = float(version)

    def request(self, method, params=[]):
        if not isinstance(method, str):
            raise ValueError('Method name must be a string.')
        if not self.id:
            self.id = ''.join(random.choice(IDCHARS) for _ in range(8))
        request = {'id': self.id, 'method': method}
        if params:
            request['params'] = params
        if self.version >= 2:
            request['jsonrpc'] = str(self.version)
        return request

    def notify(self, method, params=[]):
        request = self.request(method, params)
        if self.version >= 2:
            del request['id']
        else:
            request['id'] = None
        return request


def dumps(params=[], methodname=None, methodresponse=None, encoding=None, rpcid=None, version=None, notify=None):
    if not version:
        version = 2.0
    if isinstance(methodname, str) and not isinstance(params, (tuple, list, dict)):
        raise TypeError('Params must be a dict, list, tuple or Fault instance.')
    payload = Payload(rpcid=rpcid, version=version)
    if not encoding:
        encoding = 'utf-8'
    if methodresponse is True:
        if rpcid is None:
            raise ValueError('A method response must have an rpcid.')
        response = payload.response(params)
        return jdumps(response, encoding=encoding)
    if notify is True:
        request = payload.notify(methodname, params)
    else:
        request = payload.request(methodname, params)
    return jdumps(request, encoding=encoding)


def loads(data):
    if data == '':
        return None
    result = jloads(data)
    return result


def check_for_errors(result):
    if not result:
        return result
    if not isinstance(result, dict):
        raise TypeError('Response is not a dict.')
    if 'jsonrpc' in result.keys() and float(result['jsonrpc']) > 2.0:
        raise NotImplementedError('JSON-RPC version not yet supported.')
    if 'result' not in result.keys() and 'error' not in result.keys():
        raise ValueError('Response does not have a result or error key.')
    if 'error' in result.keys() and result['error'] is not None:
        code = result['error']['code']
        message = result['error']['message']
        raise ProtocolError((code, message))
    return result


class ServerProxy(object):
    def __init__(self, uri, transport=None, encoding=None, verbose=0, version=None):
        from urllib.parse import splittype, splithost
        if not version:
            version = 2.0
        self.__version = version
        schema, uri = splittype(uri)
        if schema not in ('http', 'https', 'unix'):
            raise IOError('Unsupported JSON-RPC protocol.')
        if schema == 'unix':
            if not USE_UNIX_SOCKETS:
                raise UnixSocketMissing("Unix sockets not available.")
            self.__host = uri
            self.__handler = '/'
        else:
            self.__host, self.__handler = splithost(uri)
            if not self.__handler:
                self.__handler = '/'
        if transport is None:
            if schema == 'unix':
                transport = UnixTransport()
            else:
                transport = Transport()
        self.__transport = transport
        self.__encoding = encoding
        self.__verbose = verbose

    def _request(self, methodname, params, rpcid=None):
        request = dumps(params, methodname, encoding=self.__encoding, rpcid=rpcid, version=self.__version)
        response = self._run_request(request)
        check_for_errors(response)
        return response['result']

    def _run_request(self, request, notify=None):
        response = self.__transport.request(self.__host, self.__handler, request, verbose=self.__verbose)
        if not response:
            return None
        return_obj = loads(response)
        return return_obj

    def __getattr__(self, name):
        def method(*args, **kwargs):
            if len(args) > 0 and len(kwargs) > 0:
                raise ProtocolError('Cannot use both positional and keyword arguments (according to JSON-RPC spec.)')
            if len(args) > 0:
                return self._request(name, args)
            else:
                return self._request(name, kwargs)
        return method
